import{_ as t,o as a,c as s,ae as o}from"./chunks/framework.BajMXG5H.js";const m=JSON.parse('{"title":"Smart Cue System","description":"","frontmatter":{},"headers":[],"relativePath":"guide/smart-cue-system.md","filePath":"guide/smart-cue-system.md"}'),i={name:"guide/smart-cue-system.md"};function n(r,e,d,u,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="smart-cue-system" tabindex="-1">Smart Cue System <a class="header-anchor" href="#smart-cue-system" aria-label="Permalink to &quot;Smart Cue System&quot;">​</a></h1><p>The Cue System is Orchestra&#39;s notification mechanism. When a session needs your attention, a cue appears at the top of the dashboard.</p><h2 id="what-triggers-a-cue" tabindex="-1">What Triggers a Cue? <a class="header-anchor" href="#what-triggers-a-cue" aria-label="Permalink to &quot;What Triggers a Cue?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trigger</th><th>Cue Type</th><th>Description</th></tr></thead><tbody><tr><td>Claude stops responding</td><td>WAITING_INPUT</td><td>Session needs your input to continue</td></tr><tr><td>Permission requested</td><td>WAITING_PERMISSION</td><td>Claude needs approval for a tool use</td></tr><tr><td>Session error</td><td>ERROR</td><td>Something went wrong</td></tr><tr><td>Stale session</td><td>WAITING_INPUT</td><td>No activity for the configured timeout period</td></tr></tbody></table><h2 id="cue-lane" tabindex="-1">Cue Lane <a class="header-anchor" href="#cue-lane" aria-label="Permalink to &quot;Cue Lane&quot;">​</a></h2><p>Cues appear in a dedicated lane at the top of the dashboard. Each cue shows:</p><ul><li><strong>Session name</strong> — Which session needs attention</li><li><strong>Reason</strong> — Why the cue was created</li><li><strong>Description</strong> — Last log message for context</li><li><strong>Jump button</strong> — Navigate directly to the session</li><li><strong>Dismiss button</strong> — Remove the cue without jumping</li></ul><h2 id="auto-resolution" tabindex="-1">Auto-Resolution <a class="header-anchor" href="#auto-resolution" aria-label="Permalink to &quot;Auto-Resolution&quot;">​</a></h2><p>Cues are automatically resolved when:</p><ul><li>The session starts running again (new tool use detected)</li><li>The session ends</li><li>You manually dismiss the cue</li></ul><h2 id="sound-notifications" tabindex="-1">Sound Notifications <a class="header-anchor" href="#sound-notifications" aria-label="Permalink to &quot;Sound Notifications&quot;">​</a></h2><p>When a new cue appears, Orchestra plays a system sound (Glass) to alert you. This works even when the app is in the background.</p><h2 id="stale-session-detection" tabindex="-1">Stale Session Detection <a class="header-anchor" href="#stale-session-detection" aria-label="Permalink to &quot;Stale Session Detection&quot;">​</a></h2><p>If a running session hasn&#39;t received any hook events for a configurable timeout period, Orchestra automatically creates a WAITING_INPUT cue. This catches cases where Claude Code has stopped but the Stop hook didn&#39;t fire.</p>',14)])])}const p=t(i,[["render",n]]);export{m as __pageData,p as default};
